/**
 * trait-performance-llama.js
 * ---------------------------------------------------------------------
 * Interactive version of the "lowest/highest-performing trait probes"
 * figure (the "Top-Bottom Probes" section / top_bottom_peak_perf.png in
 * figure_workspace/tables_and_figures.ipynb), across all three models.
 *
 * The static paper figure is a horizontal bar chart, one per model, each
 * trait's bar showing its peak-layer F1 with the trait name set inside
 * the bar and the peak layer written beside it. Here it's a single
 * vertical bar chart with 95% CI error bars, the peak layer as an
 * on-bar annotation, and full detail (trait, SCM dimension, valence,
 * F1 ± CI, layer) on hover, plus things the static figure can't do:
 *
 *  - A segmented control above the plot switches between the default
 *    "top/bottom 7" view (sorted by F1, highest-performing on the left,
 *    lowest on the right, split by a divider) and an "all 235 traits"
 *    view (one continuous descending sort, x-axis labels hidden since
 *    235 of them would just collide).
 *  - A second segmented control below the plot switches which model's
 *    results are shown (Llama-3.2-1B-Instruct / Gemma-3-1B-It /
 *    OLMo-2-0425-1B-Instruct). The top/bottom-vs-all mode and any
 *    legend-based dimension filtering carry over across a model switch,
 *    since both describe how the figure is being read, not which
 *    model's data is loaded.
 *  - Legend-click filtering by SCM dimension works out of the box here
 *    (unlike the EFA widget) since each dimension really is its own
 *    Plotly trace — no per-point color arrays to fight. In the
 *    top/bottom view specifically, filtering a dimension out doesn't
 *    just delete its bars: the group re-fills from the next-best/worst
 *    traits among the dimensions still shown, so there are always 7 (or
 *    fewer, if very few traits remain) bars per side.
 *
 * TRAIT_PERF_DATA (defined just above this IIFE) is generated by
 * figure_workspace/interactive_figures/build_trait_performance_data.py
 * and carries all 235 traits (not just the top/bottom 14) for each of
 * the three models, keyed by model slug, so the widget can recompute
 * the top/bottom slice and the "all traits" view client-side — and
 * switch models — without a page reload. Regenerate that JSON and paste
 * it in to refresh this widget.
 */
(function () {
  const el = document.getElementById("trait-performance-llama-canvas");
  if (!el || typeof Plotly === "undefined" || typeof TRAIT_PERF_DATA === "undefined") return;

  const MODEL_ORDER = TRAIT_PERF_DATA.modelOrder;
  let modelSlug = MODEL_ORDER[0];

  function activeModel() {
    return TRAIT_PERF_DATA.models[modelSlug];
  }

  const DICT_ORDER = ["sociability", "morality", "assertiveness", "ability"];
  const DICT_LABEL = {
    sociability: "Sociability",
    morality: "Morality",
    assertiveness: "Assertiveness",
    ability: "Ability",
  };

  // A 4-slot categorical set validated with the dataviz skill's
  // colorblind-safety checker (all-pairs, since which two dimensions end
  // up adjacent depends on the sorted F1 data, not a fixed order) —
  // blue/yellow/magenta/green from the palette's 8-hue set. Every bar
  // also carries a direct label (its trait name, on the x-axis, in the
  // top/bottom view) and a legend, which is the required secondary
  // encoding for the pairs that only clear the CVD floor band rather
  // than the full target.
  const DICT_COLOR = {
    sociability: { light: "#2a78d6", dark: "#3987e5" },
    morality: { light: "#eda100", dark: "#c98500" },
    assertiveness: { light: "#e87ba4", dark: "#d55181" },
    ability: { light: "#008300", dark: "#008300" },
  };

  function cssVar(name) {
    return getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  }

  function isDark() {
    return document.documentElement.getAttribute("data-theme") === "dark";
  }

  function dictColor(dict) {
    return DICT_COLOR[dict][isDark() ? "dark" : "light"];
  }

  // One blank category between the high-F1 and low-F1 groups (top/bottom
  // view only) so they read as two clusters (mirrors the notebook's
  // axhline divider), rather than 14 bars that look like one continuous
  // ranking.
  const SPACER = "";

  // Dict categories currently hidden via legend click.
  const hiddenDicts = new Set();

  // "topBottom" (default) or "all" — driven by the segmented control.
  let mode = "topBottom";

  function activeTraits() {
    return activeModel().traits.filter((t) => !hiddenDicts.has(t.dict));
  }

  // Picks the traits to actually plot for the current mode + filter
  // state, and the x-axis category order (highest F1 on the left).
  // Returns { cats, high, low } for "topBottom" ({ low, high } are the
  // trait lists so buildGroupAnnotations/buildLayerAnnotations know the
  // split) or { cats, all } for "all".
  function computeDisplay() {
    const active = activeTraits();
    if (mode === "all") {
      const sorted = active.slice().sort((a, b) => b.f1_mean - a.f1_mean);
      return { cats: sorted.map((t) => t.term), all: sorted, high: [], low: [] };
    }

    const n = activeModel().numPerGroup;
    const asc = active.slice().sort((a, b) => a.f1_mean - b.f1_mean);
    // Normally the n lowest and n highest. If filtering has left fewer
    // than 2n traits, split what's left evenly instead of letting the
    // two groups overlap.
    let low, high;
    if (asc.length <= 2 * n) {
      const half = Math.ceil(asc.length / 2);
      low = asc.slice(0, half);
      high = asc.slice(half);
    } else {
      low = asc.slice(0, n);
      high = asc.slice(asc.length - n);
    }
    // Highest-performing on the left: high group descending, spacer,
    // then low group continuing the descent.
    const highDesc = high.slice().reverse();
    const lowDesc = low.slice().reverse();
    const cats = highDesc.map((t) => t.term).concat([SPACER]).concat(lowDesc.map((t) => t.term));
    return { cats, high: highDesc, low: lowDesc, all: [] };
  }

  // The real bars naturally drop to 0 points for a dict once it's fully
  // filtered out (computeDisplay already excludes hidden dicts upstream),
  // so these never need their own legend entry — that job belongs to the
  // proxy traces below. A bar trace with 0 points also can't be clicked
  // back on via the legend (Plotly drops empty-data legend swatches
  // regardless of a "legendonly" visible flag), which is the reason for
  // the split.
  function buildRealTraces(display) {
    const shown = mode === "all" ? display.all : display.high.concat(display.low);
    return DICT_ORDER.map((d) => {
      const x = [];
      const y = [];
      const err = [];
      const customdata = [];
      shown.forEach((t) => {
        if (t.dict !== d) return;
        x.push(t.term);
        y.push(t.f1_mean);
        err.push(t.f1_se);
        customdata.push(
          `<b>${t.term}</b><br>${DICT_LABEL[t.dict]} (${t.dir})<br>` +
            `F1: ${t.f1_mean.toFixed(3)} ± ${t.f1_se.toFixed(3)}<br>Peak layer: ${t.layer}`
        );
      });
      return {
        x,
        y,
        customdata,
        hovertemplate: "%{customdata}<extra></extra>",
        type: "bar",
        name: DICT_LABEL[d],
        marker: { color: dictColor(d) },
        showlegend: false,
        error_y: {
          type: "data",
          array: err,
          visible: true,
          color: cssVar("--color-ink-muted"),
          thickness: mode === "all" ? 1 : 1.5,
          width: mode === "all" ? 0 : 4,
        },
      };
    });
  }

  // Legend-only proxy traces (the standard Plotly idiom: a marker trace
  // with a single null-coordinate point, so nothing is ever plotted).
  // These are what the legend actually shows and what plotly_legendclick
  // fires on — kept alive independent of whether the matching dict
  // currently has any bars on screen, so a fully-filtered-out dimension
  // can still be clicked back on.
  function buildProxyTraces() {
    return DICT_ORDER.map((d) => ({
      x: [null],
      y: [null],
      type: "scatter",
      mode: "markers",
      marker: { size: 10, symbol: "square", color: dictColor(d) },
      name: DICT_LABEL[d],
      showlegend: true,
      hoverinfo: "skip",
      visible: hiddenDicts.has(d) ? "legendonly" : true,
      _filterDict: d,
    }));
  }

  // Per-bar "L{layer}" annotations — only shown in the top/bottom view;
  // with 235 bars in the "all" view they'd be unreadable clutter (the
  // layer is still available on hover there).
  function buildLayerAnnotations(display) {
    if (mode !== "topBottom") return [];
    const ink = cssVar("--color-ink-muted");
    return display.high.concat(display.low).map((t) => ({
      x: t.term,
      y: t.f1_mean + t.f1_se,
      xref: "x",
      yref: "y",
      text: `L${t.layer}`,
      showarrow: false,
      yshift: 12,
      font: { family: cssVar("--font-sans"), size: 11, color: ink },
    }));
  }

  function buildGroupAnnotations(display) {
    if (mode !== "topBottom") return [];
    const nHigh = display.high.length;
    const nLow = display.low.length;
    const ink = cssVar("--color-ink");
    // Centered over each cluster, in x-axis "category index" space (0-based,
    // spacer included) via xref "x" + category position.
    return [
      {
        x: (nHigh - 1) / 2,
        y: 1.06,
        xref: "x",
        yref: "paper",
        text: "<b>Highest-performing</b>",
        showarrow: false,
        font: { family: cssVar("--font-sans"), size: 12, color: ink },
      },
      {
        x: nHigh + (nLow - 1) / 2 + 1,
        y: 1.06,
        xref: "x",
        yref: "paper",
        text: "<b>Lowest-performing</b>",
        showarrow: false,
        font: { family: cssVar("--font-sans"), size: 12, color: ink },
      },
    ];
  }

  function buildLayout(display) {
    const border = cssVar("--color-border-strong");
    const layout = {
      margin: { t: 40, r: 16, b: mode === "all" ? 40 : 90, l: 56 },
      paper_bgcolor: "transparent",
      plot_bgcolor: "transparent",
      barmode: "overlay",
      showlegend: true,
      legend: {
        orientation: "h",
        x: 0.5,
        xanchor: "center",
        y: -0.32,
        font: { family: cssVar("--font-sans"), color: cssVar("--color-ink"), size: 12 },
      },
      font: { family: cssVar("--font-sans"), color: cssVar("--color-ink") },
      bargap: mode === "all" ? 0.15 : 0.45,
      xaxis: {
        type: "category",
        categoryorder: "array",
        categoryarray: display.cats,
        tickangle: -40,
        tickfont: { size: 11 },
        showticklabels: mode !== "all",
        showgrid: false,
        automargin: true,
      },
      yaxis: {
        title: { text: "Probe F1 score", font: { size: 13 } },
        range: [0, 1],
        gridcolor: cssVar("--color-border"),
        zeroline: true,
        zerolinecolor: border,
      },
      annotations: buildLayerAnnotations(display).concat(buildGroupAnnotations(display)),
    };
    if (mode === "topBottom") {
      layout.shapes = [
        {
          type: "line",
          xref: "x",
          x0: display.high.length,
          x1: display.high.length,
          yref: "paper",
          y0: 0,
          y1: 1,
          line: { color: border, width: 1, dash: "dash" },
        },
      ];
    } else {
      layout.shapes = [];
    }
    return layout;
  }

  function render() {
    const display = computeDisplay();
    const traces = buildProxyTraces().concat(buildRealTraces(display));
    Plotly.react(el, traces, buildLayout(display), {
      displayModeBar: false,
      responsive: true,
    });
  }

  render();

  // Legend-click filtering is handled entirely ourselves (returning
  // false to suppress Plotly's default toggle): toggling a dimension
  // off doesn't just hide its bars, it changes *which* traits are
  // shown, since the top/bottom groups re-fill from the traits that are
  // now the next-most-extreme among the remaining dimensions. That
  // needs a full recompute of categories/traces/annotations, not a
  // simple visibility flip.
  el.on("plotly_legendclick", function (evt) {
    const trace = evt.data[evt.curveNumber];
    const dict = trace && trace._filterDict;
    if (!dict) return true;
    if (hiddenDicts.has(dict)) hiddenDicts.delete(dict);
    else hiddenDicts.add(dict);
    render();
    return false;
  });

  const thumb = document.getElementById("trait-performance-llama-thumb");
  const buttons = Array.from(document.querySelectorAll("#trait-performance-llama-control .segmented-btn"));

  function moveThumb(btn) {
    if (!thumb) return;
    thumb.style.width = btn.offsetWidth + "px";
    thumb.style.transform = `translateX(${btn.offsetLeft}px)`;
  }

  buttons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.mode;
      if (id === mode) return;
      buttons.forEach((b) => {
        b.classList.remove("is-active");
        b.setAttribute("aria-selected", "false");
      });
      btn.classList.add("is-active");
      btn.setAttribute("aria-selected", "true");
      moveThumb(btn);
      mode = id;
      render();
    });
  });

  const activeBtn = buttons.find((b) => b.classList.contains("is-active")) || buttons[0];
  if (activeBtn) requestAnimationFrame(() => moveThumb(activeBtn));

  window.addEventListener("resize", () => {
    const btn = buttons.find((b) => b.classList.contains("is-active"));
    if (btn) moveThumb(btn);
  });

  // Bottom segmented control: switches which model's data is plotted.
  // Mirrors the top mode-control wiring above; mode/hiddenDicts state is
  // left untouched by a model switch since neither depends on which
  // model is loaded.
  const modelThumb = document.getElementById("trait-performance-llama-model-thumb");
  const modelButtons = Array.from(
    document.querySelectorAll("#trait-performance-llama-model-control .segmented-btn")
  );

  function moveModelThumb(btn) {
    if (!modelThumb) return;
    modelThumb.style.width = btn.offsetWidth + "px";
    modelThumb.style.transform = `translateX(${btn.offsetLeft}px)`;
  }

  modelButtons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const slug = btn.dataset.model;
      if (slug === modelSlug) return;
      modelButtons.forEach((b) => {
        b.classList.remove("is-active");
        b.setAttribute("aria-selected", "false");
      });
      btn.classList.add("is-active");
      btn.setAttribute("aria-selected", "true");
      moveModelThumb(btn);
      modelSlug = slug;
      render();
    });
  });

  const activeModelBtn = modelButtons.find((b) => b.classList.contains("is-active")) || modelButtons[0];
  if (activeModelBtn) requestAnimationFrame(() => moveModelThumb(activeModelBtn));

  window.addEventListener("resize", () => {
    const btn = modelButtons.find((b) => b.classList.contains("is-active"));
    if (btn) moveModelThumb(btn);
  });

  // Re-render (colors/tokens depend on cssVar) when the site's dark-mode
  // toggle flips.
  const observer = new MutationObserver(render);
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
})();
